function cleanJsonString(raw) {
  let s = String(raw ?? "").trim();
  s = s.replace(/^```json\s*/i, "").replace(/^```\s*/i, "").replace(/```$/i, "").trim();
  return s;
}

const raw = cleanJsonString($json?.choices?.[0]?.message?.content);
if (!raw) throw new Error("Groq returned no message content.");

let data;
try {
  data = JSON.parse(raw);
} catch (e) {
  throw new Error("Groq returned invalid JSON: " + e.message + "\nRAW:\n" + raw.slice(0, 4000));
}

const allowedTemplates = ['title','bullet-reveal','big-number','quote','story'];
const allowedSettings = ['home','office','kitchen','street','school','gym','nature','city','bedroom','lab','space','workshop','abstract'];
const allowedActions = ['idle','walk','run','jump','sleep','think','laugh','cry','point','hold','read','write','talk','look','react','celebrate','search','open','throw','catch','build','discover','panic','fall'];
const allowedObjects = ['phone','laptop','book','brain','coffee','clock','calendar','mail','notification','heart','money','chart','check','warning','lightbulb','rocket','car','bike','house','desk','bed','dumbbell','trophy','gift','cloud','sun','moon','star','door','plant','chair','bag','headphones','cup','key','ball','box','tree','food','magnifier','paper','map','alarm','pencil','medal'];
const allowedCameras = ['static','push','pull','panLeft','panRight','tilt','follow','whip'];
const allowedTransitions = ['cut','push','whip','match','reveal'];

const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
const hex=(v,f)=>/^#[0-9a-f]{6}$/i.test(String(v||''))?String(v):f;
const words=(s)=>String(s||'').trim().split(/\s+/).filter(Boolean);

if (!Array.isArray(data.scenes)) throw new Error("Generated plan has no scenes array.");
if (data.scenes.length < 5 || data.scenes.length > 7) throw new Error(`Generated ${data.scenes.length} scenes. Need 5–7.`);

const scenes = data.scenes.map((s, si) => {
  const setting = allowedSettings.includes(s.setting) ? s.setting : 'abstract';
  const chars = Array.isArray(s.characters) ? s.characters.slice(0,3).map((c,ci)=>({
    id: String(c.id || `char${ci+1}`),
    role: String(c.role || (ci===0?'main character':'secondary character')).slice(0,80),
    color: hex(c.color, ci===0 ? '#52d8ff' : '#ff7aa8'),
    x: clamp(Number(c.x)|| (ci===0?420:760), 100, 980),
    y: clamp(Number(c.y)||1450, 900, 1600),
    scale: clamp(Number(c.scale)|| (ci===0?1:0.82), .5, 1.25)
  })) : [];
  if (!chars.length) chars.push({id:'main',role:'main character',color:'#52d8ff',x:420,y:1450,scale:1});

  const objs = Array.isArray(s.objects) ? s.objects.slice(0,8).map((o,oi)=>({
    id: String(o.id || `obj${oi+1}`),
    type: allowedObjects.includes(o.type) ? o.type : 'box',
    x: clamp(Number(o.x)|| (220 + (oi%4)*210), 100, 980),
    y: clamp(Number(o.y)|| (600 + (Math.floor(oi/4))*350), 250, 1500),
    scale: clamp(Number(o.scale)||.65, .35, 1.3),
    rotation: Number.isFinite(Number(o.rotation)) ? Number(o.rotation) : 0,
    layer: ['back','mid','front'].includes(o.layer) ? o.layer : 'mid'
  })) : [];
  if (objs.length < 4) throw new Error(`Scene ${si+1} has fewer than 4 objects.`);

  const objectIds = new Set(objs.map(o=>o.id));
  const charIds = new Set(chars.map(c=>c.id));
  const fallbackActor = chars[0].id;

  const beats = Array.isArray(s.beats) ? s.beats.slice(0,9).map((b,bi)=>({
    id: String(b.id || `b${bi+1}`),
    start: clamp(Number(b.start),0,.99),
    end: clamp(Number(b.end),.01,1),
    event: String(b.event || `Beat ${bi+1}`).slice(0,70),
    actor: charIds.has(String(b.actor)) ? String(b.actor) : fallbackActor,
    action: allowedActions.includes(b.action) ? b.action : (bi%3===0?'react':bi%3===1?'look':'discover'),
    objects: Array.isArray(b.objects) ? b.objects.map(String).filter(id=>objectIds.has(id)).slice(0,5) : [],
    camera: allowedCameras.includes(b.camera) ? b.camera : (bi%3===1?'push':bi%3===2?'follow':'static'),
    emphasis: b.emphasis === true,
    mood: ['calm','curious','tense','funny','surprise','triumph'].includes(b.mood) ? b.mood : 'curious'
  })).sort((a,b)=>a.start-b.start) : [];

  if (beats.length < 6 || beats.length > 9) throw new Error(`Scene ${si+1} must have 6-9 visual beats.`);
  for (let bi = 0; bi < beats.length; bi++) {
    const b = beats[bi];
    if (!(b.start >= 0 && b.start < b.end && b.end <= 1)) throw new Error(`Scene ${si+1} beat ${bi+1} has invalid timing.`);
    if (!b.objects.length) throw new Error(`Scene ${si+1} beat ${bi+1} must reference at least one object.`);
  }
  for (let i=0;i<beats.length;i++) {
    const nextStart = i<beats.length-1 ? beats[i+1].start : 1;
    beats[i].start = clamp(beats[i].start, i===0?0:beats[i-1].start+0.01, .99);
    beats[i].end = Math.max(beats[i].start+0.04, Math.min(1,nextStart));
    if (!beats[i].objects.length) beats[i].objects = objs.slice(0, Math.min(3, objs.length)).map(o=>o.id);
  }

  const narration = String(s.narration || '').trim();
  if (words(narration).length < 12 || words(narration).length > 22) {
    throw new Error(`Scene ${si+1} narration must be 12–22 words: "${narration}"`);
  }

  return {
    template: allowedTemplates.includes(s.template) ? s.template : 'story',
    text: words(s.text).slice(0,6).join(' '),
    narration,
    setting,
    characters: chars,
    objects: objs,
    beats,
    transition: allowedTransitions.includes(s.transition) ? s.transition : 'cut'
  };
});

const voiceover = scenes.map(s=>s.narration).join(' ').trim();
const wc = words(voiceover).length;
if (wc < 90 || wc > 120) throw new Error(`Voiceover is ${wc} words. Need 90–120.`);

const theme = {
  background: hex(data.theme?.background,'#0c1220'),
  accent: hex(data.theme?.accent,'#52d8ff'),
  text: hex(data.theme?.text,'#ffffff'),
  accent2: hex(data.theme?.accent2,'#ff7aa8')
};

return [{json:{
  title: String(data.title || 'AI Short').trim().slice(0,80),
  voiceover,
  theme,
  language: String($('Video input').first().json.language || 'en'),
  scenes,
  seed: Number($('Video input').first().json.seed || 0)
}}];
